// Тикет #26ca8b97 (26ca8b97f0071246c8bc9c09) — עבר QA 13.10.2026, iPhone, TestFlight 1.0.0 (19).
// Факт 13.10: во вкладке «תהילים» поле поиска с placeholder «חיפוש לפי מספר פרק או מילים» — текст выровнен вправо, есть лупа;
// то же во вкладке «פרקי אבות» (скрины 26ca8b97-ios-b19-tehilim-search-rtl.png, 26ca8b97-ios-b19-pirkei-avot-search-rtl.png).
// Геометрия: если placeholder — отдельный текстовый элемент, центр его рамки правее середины поля. Если placeholder живёт внутри
// TextField (атрибут placeholderValue) — позиция букв не видна → @manual-check (сверить по скрину); лупа — то же.
// ОБНОВЛЕНО 25.10 (#07cdd6 d6a68154, עבר QA): у «פרקי אבות» свой placeholder «חיפוש לפי מילים מתוך הפרקים» (Figma 641:2687),
// у «תהילים» прежний. Экран после #4cfbf19e — под вкладкой «ברכות» (openTehilimScreen, запасной путь «תהילים»).
import { driver, expect } from '@wdio/globals';
import { byLabel } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { searchField, tapTextInMiddle, shown } from '../_lib/app-0710.ts';
import { rectOf, staticText } from '../_lib/app-1310.ts';
import { openTehilimScreen, PH_TEHILIM, PH_AVOT } from '../_lib/app-2510.ts';

async function checkPlaceholderRight(where: string, PLACEHOLDER: string) {
  const field = await searchField();
  await field.waitForDisplayed({ timeout: 20000 });
  await field.clearValue();
  const f = await rectOf(field);

  // 1. Текст placeholder есть (атрибут поля или отдельный текст).
  const attr = driver.isIOS
    ? (await field.getAttribute('placeholderValue').catch(() => null)) ?? (await field.getAttribute('value').catch(() => null))
    : await field.getText();
  const ph = staticText(PLACEHOLDER);
  const separate = await shown(ph);
  expect(separate || (attr ?? '').includes(PLACEHOLDER)).toBe(true);

  // 2. Выравнивание вправо.
  if (separate) {
    const p = await rectOf(ph);
    if (p.width < f.width * 0.9) {
      expect(p.x + p.width / 2).toBeGreaterThan(f.x + f.width / 2);
    } else {
      console.log(`[TL-04] ${where}: рамка placeholder на всю ширину поля — @manual-check выравнивание по скрину`);
    }
  } else {
    console.log(`[TL-04] ${where}: placeholder внутри TextField — @manual-check выравнивание вправо по скрину`);
  }

  // 3. Лупа: подпись доступности (если есть) — иначе @manual-check. TODO калибровка: label иконки.
  const icon = await byLabel('חיפוש');
  if (await icon.isExisting().catch(() => false)) await expect(icon).toBeDisplayed();
  else console.log(`[TL-04] ${where}: у лупы нет подписи — @manual-check, иконка видна слева/справа от текста по макету`);
}

describe('Список תהילים', () => {
  afterEach(async () => { await toHome(); });

  it('TL-04 Поиск «תהילים» («חיפוש לפי מספר פרק או מילים») и «פרקי אבות» («חיפוש לפי מילים מתוך הפרקים»): placeholder справа, лупа #26ca8b97 #07cdd6 @prod-safe @manual-check', async () => {
    await openTehilimScreen();
    await tapTextInMiddle('תהילים');
    await checkPlaceholderRight('תהילים', PH_TEHILIM);
    await tapTextInMiddle('פרקי אבות');
    await checkPlaceholderRight('פרקי אבות', PH_AVOT);
    await tapTextInMiddle('תהילים');
  });
});
